public abstract class DocumentProcessor {
    // Superclass method returning a generic base type
    public abstract Document parse(String path);
}

public class PdfDocumentProcessor extends DocumentProcessor {
    // Covariant return type: PdfDocument is a subtype of Document
    @Override
    public PdfDocument parse(String path) {
        return new PdfDocument(path);
    }
}

// Client code usage demonstrating absence of explicit casting
public class Main {
    public static void main(String[] args) {
        DocumentProcessor processor = new PdfDocumentProcessor();
        PdfDocument doc = processor.parse("/path/to/file.pdf"); // No cast needed!
    }
}
